134	
135	
136	        return orderShipment -> {
137	            String trackingNumber = orderShipment.getTrackingNumber();
138	            Long shipmentId = orderShipment.getId();
139	
140	            if (trackingNumber == null || trackingNumber.isBlank()) {
141	                log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
142	                throw new Xpb98Exception(Xpb98ErrorCode.TRACKING_NUMBER_INVALID);
143	            }
144	
145	            log.info("배송 상태 조회 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
146	                    shipmentId, trackingNumber, orderShipment.getStatus());
147	
148	            try {
149	
150	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
151	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}", shipmentId, currentStatus);
152	
153	
154	                Xpb98Status newStatus = mapToShipmentStatus(currentStatus);
155	                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
156	
157	
158	                if (orderShipment.getStatus() == newStatus) {
159	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
160	                            shipmentId, newStatus);
161	                    return orderShipment;
