178	
179	                }
180	                else {
181	                    log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
182	                    orderShipment.updateStatus(Xpb98Status.IN_TRANSIT);
183	                }
184	
185	                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
186	                return orderShipment;
187	
188	            } catch (Exception e) {
189	                log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
190	                        shipmentId, trackingNumber, e.getMessage(), e);
191	
192	
193	                if (!(e instanceof Xpb98Exception)) {
194	                    throw new Xpb98Exception(
195	                            Xpb98ErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
196	                            "배송 상태 조회 중 오류 발생: " + e.getMessage(),
197	                            e
198	                    );
199	                }
