621	        @Override
622	        public boolean canTransitionTo(Xpb98Status nextStatus) {
623	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
624	                    || nextStatus == DELIVERED;
625	        }
626	    },
627	    OUT_FOR_DELIVERY {
628	        @Override
629	        public boolean canTransitionTo(Xpb98Status nextStatus) {
