641	        public boolean canTransitionTo(Xpb98Status nextStatus) {
642	            return nextStatus == CANCELED;
643	        }
644	    },
645	    CANCELED {
646	        @Override
647	        public boolean canTransitionTo(Xpb98Status nextStatus) {
648	            return false;
649	        }
