379	    public Xhx14 process(Xhx14 orderShipment) throws Exception {
380	        String trackingNumber = orderShipment.getTrackingNumber();
381	        Long shipmentId = orderShipment.getId();
382	
383	        if (trackingNumber == null || trackingNumber.isBlank()) {
384	            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
385	            throw new Xpb98Exception(Xpb98ErrorCode.TRACKING_NUMBER_INVALID);
386	        }
387	
388	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
389	                shipmentId, trackingNumber, orderShipment.getStatus());
390	
391	        Page page = null;
392	        try {
393	
394	            page = browserManager.newPage();
395	            if (page == null) {
396	                throw new Xpb98Exception(Xpb98ErrorCode.BROWSER_INITIALIZATION_ERROR);
397	            }
398	
399	
400	            page.setDefaultTimeout(TIMEOUT_MS);
401	
402	
403	            String url = TRACKING_URL_PREFIX + trackingNumber;
404	            log.debug("배송 조회 페이지로 이동: {}", url);
405	            page.navigate(url);
406	
407	
408	            log.debug("배송 상태 테이블 로드 대기");
409	            page.waitForSelector(STATUS_SELECTOR);
410	
411	
412	            String renderedHtml = page.content();
413	            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());
414	
415	
416	            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
417	            Xpb98Status newStatus = mapToShipmentStatus(statusText);
418	
419	            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
420	                    shipmentId, statusText, newStatus);
421	
422	
423	            if (orderShipment.getStatus() == newStatus) {
424	                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
425	                        shipmentId, newStatus);
426	                return orderShipment;
427	            }
428	
429	
430	            if (newStatus == Xpb98Status.DELIVERED) {
431	                log.info("배송 완료 처리: shipmentId={}, orderId={}",
432	                        shipmentId, orderShipment.getOrder().getId());
433	
434	
435	                orderShipment.updateStatus(Xpb98Status.DELIVERED);
436	
437	
438	                orderService.completeOrder(orderShipment.getOrder().getId());
439	                notificationService.notifyShipmentCompleted(orderShipment.getOrder());
440	
441	            } else if (newStatus == Xpb98Status.OUT_FOR_DELIVERY) {
442	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
443	                orderShipment.updateStatus(Xpb98Status.OUT_FOR_DELIVERY);
444	
445	            } else {
446	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
447	                orderShipment.updateStatus(Xpb98Status.IN_TRANSIT);
448	            }
449	
450	            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
451	                    shipmentId, orderShipment.getStatus());
452	
453	            return orderShipment;
454	
455	        } catch (Exception e) {
456	            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
457	                    shipmentId, trackingNumber, e.getMessage(), e);
458	
459	
460	            if (!(e instanceof Xpb98Exception)) {
461	                throw new Xpb98Exception(
462	                        Xpb98ErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
463	                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
464	                        e
465	                );
466	            }
467	            throw e;
468	        } finally {
469	
470	            if (page != null) {
471	                try {
472	                    page.close();
473	                    log.debug("페이지 리소스 해제 완료");
474	                } catch (Exception e) {
475	                    log.warn("페이지 닫기 실패: {}", e.getMessage());
476	                }
477	            }
478	        }
479	    }
