607	public enum Xpb98Status {
608	    PENDING {
609	        @Override
610	        public boolean canTransitionTo(Xpb98Status nextStatus) {
611	            return nextStatus == SHIPPED || nextStatus == CANCELED;
612	        }
613	    },
